import{_ as e,o as d,c as o,a5 as s}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Test — Content Writing View (FR 3.6.10)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-10-content-writting-view/test.md","filePath":"feature/content-task-workflow/3-6-10-content-writting-view/test.md"}'),r={name:"feature/content-task-workflow/3-6-10-content-writting-view/test.md"};function n(a,t,i,c,l,h){return d(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="test-—-content-writing-view-fr-3-6-10" tabindex="-1">Test — Content Writing View (FR 3.6.10) <a class="header-anchor" href="#test-—-content-writing-view-fr-3-6-10" aria-label="Permalink to &quot;Test — Content Writing View (FR 3.6.10)&quot;">​</a></h1><p>&gt; Status: <strong>Implemented &amp; executed (2026-10-12; redesign + presence + mobile port added 2026-10-26).</strong> All passing: 47+32 frontend unit + 22 backend service unit + 22 browser E2E + 31 live-backend integration (re-run 31/31 on the merged develop code) + 22 mobile unit. The live run (before merging the team&#39;s develop) found three defects the mocked tests could not see (§7 #4–#6); #4/#5 were meanwhile fixed upstream in <code>ChatInboundChannelInterceptor</code> and #6 was re-applied on top of develop. Items that could <strong>not</strong> be executed or are out of scope are listed explicitly in §6. See <a href="./spec.html">spec.md</a>, <a href="./task.html">task.md</a>. &gt; &gt; <strong>2026-10-26 addition</strong>: web UI redesigned to a Docs/Word hybrid chrome (page-card canvas + toolbar, Docs/Ribbon toggle — purely visual, zero logic changes, all pre-existing tests kept passing unmodified except the broker-mock fix noted below); presence/multi-cursor awareness added (<code>y-protocols/awareness</code> over a new unpersisted <code>/app+/topic/tasks/{taskId}/awareness</code> STOMP channel); 32 new Vitest unit tests for previously-untested pure-logic files (<code>richText.ts</code>, <code>listUtils.ts</code>, <code>contentUtils.ts</code>); 2 new E2E tests for presence (E2E-21, E2E-22); and a parallel <strong>mobile port</strong> (React Native, <code>brandhub-mobile-app/src/screens/content-writing/</code>) covering the same feature set via a TextInput-based editor instead of canvas — see §5 below.</p><h2 id="_1-summary" tabindex="-1">1. Summary <a class="header-anchor" href="#_1-summary" aria-label="Permalink to &quot;1. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Tool</th><th>Location</th><th>Cases</th><th>Result</th></tr></thead><tbody><tr><td>FE pure logic (list, diff, publish text, restore, CRDT)</td><td>Vitest</td><td><code>brandhub-web/src/pages/content-writing/**/*.test.ts</code></td><td>47 + 32 new (2026-10-26)</td><td>✅ 79 / 79</td></tr><tr><td>BE service logic (load, op log, snapshot, versions, restore)</td><td>JUnit 5 + Mockito</td><td><code>brandhub-business-service/src/test/java/.../service/impl/TaskContentServiceImplTest.java</code></td><td>22</td><td>✅ 22 / 22</td></tr><tr><td>Browser E2E (real canvas editor, mocked REST + in-test STOMP broker)</td><td>Playwright</td><td><code>brandhub-web/tests/e2e/editor/content-writing.spec.ts</code></td><td>20 + 2 new presence (E2E-21/22)</td><td>✅ 22 / 22</td></tr><tr><td><strong>Live backend integration</strong> (real Spring Boot + Postgres + JWT + STOMP; two WS clients with real Yjs)</td><td>Node script</td><td><a href="./integration-test.cjs.html">integration-test.cjs</a></td><td>31</td><td>✅ 31 / 31</td></tr><tr><td><strong>Mobile unit (new, 2026-10-26)</strong></td><td>Jest (jest-expo)</td><td><code>brandhub-mobile-app/src/screens/content-writing/__tests__/*.test.ts</code></td><td>22</td><td>✅ 22 / 22</td></tr><tr><td><strong>Mobile component (new, 2026-10-26)</strong></td><td>Jest + <code>@testing-library/react-native</code></td><td><code>brandhub-mobile-app/src/screens/content-writing/__tests__/*.test.tsx</code></td><td>24</td><td>✅ 24 / 24</td></tr><tr><td><strong>Mobile device flows (new, 2026-10-26)</strong></td><td>Maestro (YAML)</td><td><code>brandhub-mobile-app/.maestro/content-writing/*.yaml</code></td><td>7 flows</td><td>⚠️ written, not executed — see §9</td></tr></tbody></table><p>&gt; E2E note: running the full suite with Playwright&#39;s default <code>fullyParallel</code> workers against one shared <code>npm run dev</code> dev server causes spurious failures (page stuck on the app&#39;s lazy-load Suspense fallback) unrelated to this feature — confirmed by re-running with <code>--workers=1</code>, where all 22 pass, and by running each failing test in isolation. Always use <code>--workers=1</code> for this spec, or point <code>BASE_URL</code> at a dedicated dev server per worker.</p><h2 id="_2-how-to-run" tabindex="-1">2. How to run <a class="header-anchor" href="#_2-how-to-run" aria-label="Permalink to &quot;2. How to run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Frontend unit tests</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brandhub-web-dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # vitest run (src/**/*.test.ts only)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Backend unit tests</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brandhub-business-service</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Dtest=TaskContentServiceImplTest</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Browser E2E (starts `npm run dev` itself)</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brandhub-web-dashboard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/editor/content-writing.spec.ts</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Live backend integration (needs Postgres + Redis up; see &quot;Live integration setup&quot;)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WS_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspace</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uuid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration-test.cjs</span></span></code></pre></div><p>Live integration setup (used for the 2026-10-12 run): start <code>brandhub-postgres</code> + <code>brandhub-redis</code>; create a scratch DB cloned with <code>pg_dump -s brandhub | psql brandhub_e2e</code>; run business-service with <code>POSTGRES_URL=jdbc:postgresql://localhost:5432/brandhub_e2e</code>, <code>SPRING_JPA_HIBERNATE_DDL_AUTO=update</code>, <code>MONGODB_URI=mongodb://localhost:27017</code> and the JWT/Redis vars from <code>docker/.env</code>; register <code>e2e_a/b/c@test.local</code> (password <code>Passw0rdx1</code>) via <code>/api/v1/auth/register</code>, activate them in SQL (<code>status=&#39;ACTIVE&#39;, email_verified_at=now()</code>), and seed one agency + workspace with <code>e2e_a</code> as MANAGER, <code>e2e_b</code> as CREATOR and <code>e2e_c</code> as non-member. Since Tasks moved to MongoDB (develop, 2026-10): create the <code>uq_tasks_campaign_work_item</code> index on the scratch Mongo <code>tasks</code> collection (as in <code>2026-10-09-campaign-task-deployment.js</code>, otherwise <code>TASK_SCHEMA_NOT_READY</code>) and apply the FK drops from <code>2026-10-09-campaign-deployment.sql</code> to <code>task_content_*</code> (otherwise inserts fail on the old FK to Postgres <code>tasks</code>). Re-run on the merged develop code: 31/31. The script covers: REST load/RBAC (IT-01..06), WS handshake (IT-07..08), two live clients and 120-update concurrent burst (IT-09..16), snapshots/versions/who (IT-17..24), read-only restore + live propagation (IT-25..28), non-member over WS (IT-29..30), payload validation (IT-31).</p><p>Notes:</p><ul><li>First E2E run on a machine needs <code>npx playwright install chromium</code> (the installed <code>@playwright/test</code> pins a specific Chromium build).</li><li>If Maven reports <code>Unresolved compilation problems ... source level 25</code>, <code>target/</code> holds classes compiled by the IDE (ECJ); run <code>mvn clean test</code>.</li><li>E2E does <strong>not</strong> need the backend: REST is mocked with <code>page.route</code>, and the STOMP socket is a small in-test broker (<code>page.routeWebSocket</code>) that echoes each <code>SEND</code> as a <code>MESSAGE</code> with an increasing <code>sequenceNumber</code>, mirroring <code>TaskContentWebSocketController</code>.</li></ul><h2 id="_3-frontend-unit-tests-vitest" tabindex="-1">3. Frontend unit tests (Vitest) <a class="header-anchor" href="#_3-frontend-unit-tests-vitest" aria-label="Permalink to &quot;3. Frontend unit tests (Vitest)&quot;">​</a></h2><h3 id="_3-1-lists-—-listutils-test-ts" tabindex="-1">3.1 Lists — <code>listUtils.test.ts</code> <a class="header-anchor" href="#_3-1-lists-—-listutils-test-ts" aria-label="Permalink to &quot;3.1 Lists — `listUtils.test.ts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Scenario</th><th>Expected</th></tr></thead><tbody><tr><td>TC-LIST-01</td><td>Bullet on the paragraph under the caret</td><td><code>alpha</code> → <code>• alpha</code></td></tr><tr><td>TC-LIST-02</td><td>Ordered list over 3 selected paragraphs</td><td>numbered <code>1.</code> <code>2.</code> <code>3.</code></td></tr><tr><td>TC-LIST-03</td><td>Selection spans only middle paragraphs</td><td>only those paragraphs get the marker</td></tr><tr><td>TC-LIST-04</td><td>Toggle the same kind when all paragraphs already have it</td><td>markers removed</td></tr><tr><td>TC-LIST-05</td><td>Mixed (some already bullets)</td><td>all become bullets, no double prefix</td></tr><tr><td>TC-LIST-06</td><td>Bullet ⇄ ordered</td><td>marker replaced, never stacked</td></tr><tr><td>TC-LIST-07</td><td>Empty document</td><td>creates an empty first item (<code>• </code> / <code>1. </code>)</td></tr><tr><td>TC-LIST-08</td><td>Empty paragraph between two others</td><td>empty paragraph also gets a marker</td></tr><tr><td>TC-LIST-09</td><td>Text like <code>10.5 km</code> / <code>2024</code></td><td>not mistaken for an existing marker</td></tr><tr><td>TC-LIST-10</td><td>Caret after toggle</td><td>end of last affected paragraph</td></tr><tr><td>TC-LIST-11</td><td>Reversed selection (focus before anchor)</td><td>same result as forward selection</td></tr><tr><td>TC-LIST-12</td><td>Enter at end of a bullet item</td><td>continues with <code>• </code></td></tr><tr><td>TC-LIST-13</td><td>Enter in ordered item</td><td>increments (<code>2.</code>→<code>3.</code>, <code>9.</code>→<code>10.</code>)</td></tr><tr><td>TC-LIST-14</td><td>Enter on an empty item</td><td>exits the list (marker removed, no newline)</td></tr><tr><td>TC-LIST-15</td><td>Enter outside any list / empty doc</td><td>plain <code>\\n</code></td></tr><tr><td>TC-LIST-16</td><td>Enter with caret inside the marker</td><td>plain <code>\\n</code></td></tr><tr><td>TC-LIST-17</td><td>Enter in the middle of an item</td><td>marker carried to the new line</td></tr></tbody></table><h3 id="_3-2-utilities-—-contentutils-test-ts" tabindex="-1">3.2 Utilities — <code>contentUtils.test.ts</code> <a class="header-anchor" href="#_3-2-utilities-—-contentutils-test-ts" aria-label="Permalink to &quot;3.2 Utilities — `contentUtils.test.ts`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Scenario</th><th>Expected</th></tr></thead><tbody><tr><td>TC-UTIL-01..03</td><td><code>yjsStateToText</code>: null, plain text, formatted text</td><td><code>&quot;&quot;</code>, text, text (attributes ignored)</td></tr><tr><td>TC-DIFF-01</td><td>identical text</td><td>single <code>same</code> part</td></tr><tr><td>TC-DIFF-02</td><td>first version (empty before)</td><td>all <code>add</code></td></tr><tr><td>TC-DIFF-03</td><td>everything removed</td><td>all <code>del</code></td></tr><tr><td>TC-DIFF-04</td><td>replaced words</td><td><code>del</code> + <code>add</code> around unchanged context</td></tr><tr><td>TC-DIFF-05</td><td>rebuild old/new from parts</td><td>lossless (old = same+del, new = same+add)</td></tr><tr><td>TC-DIFF-06</td><td>both empty</td><td>no parts</td></tr><tr><td>TC-DIFF-07</td><td>input above the size cap</td><td>whole <code>del</code> + whole <code>add</code> (no freeze)</td></tr><tr><td>TC-FONT-01</td><td>plain text</td><td>unchanged</td></tr><tr><td>TC-FONT-02</td><td>decomposed Vietnamese (<code>e</code>+<code>◌̣</code>+<code>◌̂</code>)</td><td>NFC-normalized (<code>ệ</code>)</td></tr><tr><td>TC-FONT-03</td><td>bold <code>Az09</code></td><td>Mathematical Sans-Serif Bold letters/digits</td></tr><tr><td>TC-FONT-04</td><td>italic <code>Az1</code></td><td>Sans-Serif Italic letters; digits stay plain</td></tr><tr><td>TC-FONT-05</td><td>bold + italic</td><td>Bold-Italic set</td></tr><tr><td>TC-FONT-06</td><td>bold <code>ệ</code></td><td>styled base <code>e</code> + combining marks kept</td></tr><tr><td>TC-FONT-07</td><td>bold <code>đ! 😀</code></td><td><code>đ</code>, punctuation, emoji unchanged</td></tr><tr><td>TC-FONT-08</td><td>mixed runs</td><td>concatenated in order, plain runs untouched</td></tr><tr><td>TC-FONT-09</td><td>underline/color-only run, non-text embed</td><td>plain / skipped</td></tr><tr><td>TC-FONT-10</td><td>list prefixes</td><td>pass through as literal text</td></tr><tr><td>TC-FONT-11</td><td>empty delta</td><td><code>&quot;&quot;</code></td></tr><tr><td>TC-RESTORE-01</td><td>restore replaces current text</td><td>old text</td></tr><tr><td>TC-RESTORE-02</td><td>restored formatting</td><td>attributes preserved</td></tr><tr><td>TC-RESTORE-03</td><td>null snapshot</td><td>no-op</td></tr><tr><td>TC-RESTORE-04</td><td>empty snapshot</td><td>document cleared</td></tr><tr><td>TC-RESTORE-05</td><td>restore on client A</td><td>client B converges to restored text (restore is a normal update)</td></tr><tr><td>TC-RESTORE-06</td><td>edit by B right after restore</td><td>kept, both converge</td></tr><tr><td>TC-SYNC-01</td><td>two clients insert at the same index</td><td>identical text on both, both edits present</td></tr><tr><td>TC-SYNC-02</td><td>replay snapshot + operation tail</td><td>same delta (incl. formatting)</td></tr><tr><td>TC-SYNC-03</td><td>same update applied twice (echoed broadcast)</td><td>idempotent</td></tr></tbody></table><h2 id="_4-backend-unit-tests-junit-5-mockito-—-taskcontentserviceimpltest" tabindex="-1">4. Backend unit tests (JUnit 5 + Mockito) — <code>TaskContentServiceImplTest</code> <a class="header-anchor" href="#_4-backend-unit-tests-junit-5-mockito-—-taskcontentserviceimpltest" aria-label="Permalink to &quot;4. Backend unit tests (JUnit 5 + Mockito) — `TaskContentServiceImplTest`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Test</th><th>Verifies</th></tr></thead><tbody><tr><td><code>getContent_withoutSnapshot_returnsAllOperationsFromZero</code></td><td>no snapshot → all ops, <code>sequenceNumber</code> = last op</td></tr><tr><td><code>getContent_withSnapshot_returnsOnlyTailAfterSnapshot</code></td><td>tail starts after snapshot sequence</td></tr><tr><td><code>getContent_snapshotWithEmptyTail_reportsSnapshotSequence</code></td><td>sequence = snapshot&#39;s</td></tr><tr><td><code>getContent_taskInOtherWorkspace_isNotFound</code></td><td>cross-workspace access → <code>TASK_NOT_FOUND</code></td></tr><tr><td><code>getContent_nonPostTask_isRejected</code></td><td>non-POST → <code>INVALID_TASK_TYPE_FOR_CONTENT_WRITING</code></td></tr><tr><td><code>appendOperation_assignsNextSequenceAndRecordsEditor</code></td><td><code>count+1</code>, stores update + <code>editedBy</code> + <code>taskId</code></td></tr><tr><td><code>appendOperation_concurrentWritersNeverGetTheSameSequence</code></td><td>8 threads × 25 appends against a log that throws on duplicate sequence → 200 unique sequences, no error (guards the per-task lock)</td></tr><tr><td><code>reportSnapshot_savesWhenNoneExists</code></td><td>first snapshot persisted</td></tr><tr><td><code>reportSnapshot_skipsWhenLatestIsAtOrBeyondReportedSequence</code></td><td>equal/behind → ignored (first reporter wins)</td></tr><tr><td><code>reportSnapshot_savesWhenReportedSequenceIsNewer</code></td><td>newer → saved</td></tr><tr><td><code>reportSnapshot_wrongWorkspace_isNotFoundAndNothingSaved</code></td><td>no write on foreign workspace</td></tr><tr><td><code>listVersions_includesLastEditorUpToSnapshotSequence</code></td><td><code>editedBy</code> / <code>editedByName</code> resolved</td></tr><tr><td><code>listVersions_noOperationFound_leavesEditorNull</code></td><td>both null</td></tr><tr><td><code>listVersions_editorUserDeleted_keepsIdButNoName</code></td><td>id kept, name null</td></tr><tr><td><code>listVersions_operationWithoutEditor_doesNotQueryUsers</code></td><td>no needless user lookup</td></tr><tr><td><code>listVersions_noSnapshots_returnsEmptyList</code></td><td><code>[]</code></td></tr><tr><td><code>getVersion_returnsStoredStateWithItsSequence</code></td><td>state + sequence, empty tail</td></tr><tr><td><code>getVersion_snapshotBelongsToAnotherTask_isNotFound</code></td><td>cross-task snapshot → <code>TASK_NOT_FOUND</code></td></tr><tr><td><code>getVersion_unknownSnapshot_isNotFound</code></td><td>unknown id → <code>TASK_NOT_FOUND</code></td></tr><tr><td><code>restoreVersion_isReadOnly_returnsOldStateAndWritesNothing</code></td><td>returns old state; no snapshot/op saved</td></tr><tr><td><code>restoreVersion_doesNotShiftNextOperationSequence</code></td><td>regression: next op still <code>count+1</code>, no colliding snapshot</td></tr><tr><td><code>restoreVersion_snapshotOfAnotherTask_isNotFound</code></td><td>cross-task protection</td></tr></tbody></table><h2 id="_5-browser-e2e-playwright-—-content-writing-spec-ts" tabindex="-1">5. Browser E2E (Playwright) — <code>content-writing.spec.ts</code> <a class="header-anchor" href="#_5-browser-e2e-playwright-—-content-writing-spec-ts" aria-label="Permalink to &quot;5. Browser E2E (Playwright) — `content-writing.spec.ts`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Scenario</th><th>Expected</th></tr></thead><tbody><tr><td>E2E-01</td><td>open page</td><td>editor + canvas visible, status &quot;Live&quot; (STOMP connected)</td></tr><tr><td>E2E-02</td><td>type <code>Hello BrandHub</code></td><td>text in editor &amp; preview; Yjs updates sent over STOMP; replaying them rebuilds the text</td></tr><tr><td>E2E-03</td><td>load with existing snapshot</td><td>content restored</td></tr><tr><td>E2E-04</td><td>Vietnamese IME via CDP (<code>imeSetComposition</code> → <code>insertText</code>)</td><td>preview shown mid-composition but document/publish text empty until commit; <strong>no &quot;Maximum update depth&quot; render loop</strong></td></tr><tr><td>E2E-05</td><td><code>Ctrl+A</code>, <code>Ctrl+B</code></td><td>mirror stays plain; preview shows Unicode bold</td></tr><tr><td>E2E-06</td><td><code>Ctrl+A</code>, Backspace</td><td>document cleared</td></tr><tr><td>E2E-07</td><td>undo / redo</td><td>text removed then restored</td></tr><tr><td>E2E-08</td><td>bullet button twice</td><td><code>• buy milk</code> then back to <code>buy milk</code></td></tr><tr><td>E2E-09</td><td>select all + numbered button</td><td><code>1. one / 2. two / 3. three</code></td></tr><tr><td>E2E-10</td><td>bullet, Enter, type, Enter, Enter</td><td>list continues, then exits on empty item; focus stays in editor</td></tr><tr><td>E2E-11</td><td>versions with/without editor name</td><td>name shown / &quot;Unknown&quot;</td></tr><tr><td>E2E-12</td><td>&quot;Changes&quot;</td><td>struck words red, new words green; &quot;Hide&quot; collapses</td></tr><tr><td>E2E-13</td><td>first version &quot;Changes&quot;</td><td>all additions</td></tr><tr><td>E2E-14</td><td>&quot;Restore&quot;</td><td>live content replaced; restore sent as a Yjs update; replaying it on the old state gives restored text</td></tr><tr><td>E2E-15</td><td>no versions</td><td>placeholder</td></tr><tr><td>E2E-16</td><td>type, wait 21 s (fake clock)</td><td>exactly one <code>POST .../content/snapshot</code> with the typed text</td></tr><tr><td>E2E-17</td><td>bold text → &quot;Sao chép bản đăng&quot;</td><td>clipboard holds converted text</td></tr><tr><td>E2E-18</td><td>empty document</td><td>copy button disabled</td></tr><tr><td>E2E-19</td><td>socket dropped, edit typed offline, then reconnect</td><td>edit queued + persisted in localStorage, sent after reconnect, queue cleared; update missed while offline is pulled from REST and merged</td></tr><tr><td>E2E-20</td><td>accessibility attributes</td><td>hidden input has <code>role=textbox</code> + <code>aria-multiline</code>; canvas is <code>aria-hidden</code></td></tr><tr><td>E2E-21 <em>(new, 2026-10-26)</em></td><td>fake peer&#39;s awareness update arrives</td><td>their cursor flag renders with their name and color, <code>getByTitle(name)</code> visible</td></tr><tr><td>E2E-22 <em>(new, 2026-10-26)</em></td><td>this Creator types (publishes their own awareness state)</td><td>their own avatar never renders as a &quot;peer of itself&quot; — even though the mock broker echoes every SEND back to the sender, matching a real multi-subscriber topic</td></tr></tbody></table><p>&gt; Not covered by E2E-21: the 30s auto-expiry of a silent peer&#39;s cursor (y-protocols&#39; own <code>outdatedTimeout</code>). <code>lib0</code>&#39;s <code>getUnixTime</code> captures a direct <code>Date.now</code> reference at module load, which Playwright&#39;s <code>page.clock</code> fake-timer patch (applied after that module already loaded) cannot retroactively intercept — a library/clock-mocking limitation, not an app-code gap. The removal behavior itself is a well-established y-protocols guarantee, not something this feature&#39;s code implements.</p><h2 id="_6-not-executed-known-gaps" tabindex="-1">6. Not executed / known gaps <a class="header-anchor" href="#_6-not-executed-known-gaps" aria-label="Permalink to &quot;6. Not executed / known gaps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Status</th><th>Why / next step</th></tr></thead><tbody><tr><td>Real backend integration (Postgres unique constraint, handshake, <code>@RequireRole</code>, STOMP controller, new <code>GET .../versions/{id}</code>)</td><td>✅ <strong>Run 2026-10-12</strong></td><td><code>integration-test.cjs</code>, 31/31, against a real business-service + Postgres scratch DB. Mongo was pointed at the local instance; api-gateway, ai/publisher services and RabbitMQ were not started.</td></tr><tr><td>Two live clients</td><td>✅ <strong>Run</strong> (headless WS clients, real Yjs)</td><td>IT-09..16, 28. Two real <em>browser tabs</em> against the live backend were not run; the browser path is covered by the mock-broker E2E.</td></tr><tr><td>Full browser → gateway → backend run</td><td><strong>Not run</strong></td><td>Gateway not started; the frontend&#39;s real <code>useTaskContentSync</code> against the live backend was not exercised (the Node client mirrors it).</td></tr><tr><td>Pre-existing failures elsewhere in business-service</td><td>Out of scope</td><td>Startup logs show unrelated missing tables (<code>admin_notifications</code>, <code>admin_email_outbox</code>, <code>admin_report_exports</code>) in the cloned schema; <code>/actuator/health</code> reports DOWN. Not touched.</td></tr><tr><td>Screen reader</td><td>Partial</td><td>Only that the hidden <code>aria-live</code> mirror tracks the document (E2E-02..10); no real AT run.</td></tr><tr><td>Offline resilience</td><td>✅ E2E-19</td><td>In-memory + localStorage queue and REST resync on reconnect. Not covered: a real network outage against a live backend, token refresh during a long outage.</td></tr><tr><td>Virtualization</td><td>Out of scope</td><td>Not implemented (see <a href="./task.html">task.md</a> #8).</td></tr><tr><td>Mutation check of the per-task lock</td><td>✅ Effectively done</td><td>The live burst (IT-13) failed with the old lock-inside-<code>@Transactional</code> code (228 duplicate-key errors) and passes after the fix. The Mockito concurrency test could <strong>not</strong> catch this because mocks have no transactions.</td></tr><tr><td>Rendering of styled Unicode on target platforms</td><td>Manual</td><td>Facebook/TikTok/Zalo rendering of Vietnamese styled letters varies by font; verify manually before relying on it.</td></tr><tr><td>Wrapped-line hanging indent / mid-list renumbering</td><td>Known limitation</td><td>Lists are literal text prefixes (see spec.md).</td></tr></tbody></table><h2 id="_7-defects-found-and-fixed-while-testing" tabindex="-1">7. Defects found and fixed while testing <a class="header-anchor" href="#_7-defects-found-and-fixed-while-testing" aria-label="Permalink to &quot;7. Defects found and fixed while testing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Defect</th><th>Found by</th><th>Fix</th></tr></thead><tbody><tr><td>1</td><td>After clicking a toolbar button, focus left the hidden input so the next keystrokes were lost (list items couldn&#39;t be typed right after pressing the button)</td><td>E2E-10</td><td><code>toggleList</code> returns focus to the hidden input</td></tr><tr><td>2</td><td>During IME composition the editor re-rendered in a loop (<code>Maximum update depth exceeded</code>): <code>displayRuns</code> was a new array every render, so <code>render</code> changed identity and its effect called <code>setCaretPos({...})</code> each time</td><td>E2E-04</td><td><code>displayRuns</code> memoized; <code>setCaretPos</code> bails out when the position is unchanged</td></tr><tr><td>3</td><td>Restore: live document not updated, and snapshot sequence collided with the next operation (edit lost on reload)</td><td>review + TC-RESTORE-*, <code>restoreVersion_*</code></td><td>restore is read-only on the server and applied client-side as a normal edit</td></tr><tr><td>4</td><td><strong>Task content WebSocket was completely unusable</strong>: the chat feature&#39;s global <code>ChatInboundChannelInterceptor</code> demanded an <code>Authorization</code> STOMP header on CONNECT (the editor authenticates via <code>?token=</code>) and only allowed chat destinations, so every CONNECT got <code>ERROR: Authentication required</code></td><td>live integration (IT-09)</td><td>fixed independently upstream in develop: <code>ChatInboundChannelInterceptor</code> accepts the handshake-authenticated session and <code>authorizeTask</code> handles `/app</td></tr><tr><td>5</td><td><strong>Authorization hole</strong>: <code>appendOperation</code> and the topic subscription checked no membership, so any logged-in user could subscribe to / write into any task&#39;s content log (the code comment &quot;validated by the handshake&quot; was false: the handshake only checks the JWT)</td><td>review while fixing #4, IT-29/30</td><td>upstream <code>authorizeTask</code> requires an existing POST task and an active OWNER/MANAGER/CREATOR member of its workspace for SEND and SUBSCRIBE; <code>appendOperation</code> also checks editor access</td></tr><tr><td>6</td><td><strong>Lost updates under concurrency</strong> (the earlier &quot;per-task lock&quot; fix was incomplete): <code>synchronized</code> lived inside <code>@Transactional</code>, so the lock was released before commit; a burst of 120 updates persisted only ~63, 228 <code>duplicate key</code> errors</td><td>live integration (IT-13)</td><td>removed <code>@Transactional</code> from <code>appendOperation</code> so each statement commits inside the lock (re-applied on top of develop, which still had the bug). Single-JVM only, as before</td></tr></tbody></table><p>Test-authoring mistakes (wrong expected code points, an over-narrow glob for the restore route) were corrected in the tests themselves; they were not product defects.</p><h2 id="_8-mobile-unit-tests-jest-jest-expo-—-new-2026-10-26" tabindex="-1">8. Mobile unit tests (Jest, <code>jest-expo</code>) — new, 2026-10-26 <a class="header-anchor" href="#_8-mobile-unit-tests-jest-jest-expo-—-new-2026-10-26" aria-label="Permalink to &quot;8. Mobile unit tests (Jest, `jest-expo`) — new, 2026-10-26&quot;">​</a></h2><p>Mirrors §3&#39;s web pure-logic tests exactly (same assertions, ported file-for-file) against the mobile port&#39;s own copies of the logic (<code>brandhub-mobile-app/src/screens/content-writing/{listUtils,base64,contentUtils}.ts</code>) — there is no shared package between the two apps, so these files are duplicated by design, same as the rest of the mobile codebase&#39;s relationship to web.</p><table tabindex="0"><thead><tr><th>File</th><th>Cases</th><th>Result</th></tr></thead><tbody><tr><td><code>listUtils.test.ts</code></td><td>8</td><td>✅</td></tr><tr><td><code>base64.test.ts</code></td><td>4</td><td>✅</td></tr><tr><td><code>contentUtils.test.ts</code></td><td>10</td><td>✅</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brandhub-mobile-app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/screens/content-writing</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # jest, all 3 files</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> brandhub-mobile-app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                   # full suite — confirms no regression: 11 suites / 53 tests, all passing</span></span></code></pre></div><p><strong>Environment fix needed to get yjs running under Jest</strong> (not a product bug, but required infrastructure — documented here since it will resurface for anyone adding more <code>yjs</code>-dependent tests to this app): <code>yjs</code>&#39;s <code>lib0</code> dependency resolves to its React-Native-specific <code>webcrypto.react-native.cjs</code> entry under <code>jest-expo</code>&#39;s RN-style module resolution. That file requires <code>isomorphic-webcrypto</code>, whose own &quot;no native crypto found&quot; fallback (<code>msrcrypto</code>) tries to gather entropy via <code>XMLHttpRequest</code> — undefined in Jest&#39;s plain Node test environment (a real device build never hits this path; Expo provides <code>global.crypto</code> there). Fixed with:</p><ul><li><code>react-native-get-random-values</code> imported in <code>jest.setup.ts</code> (also the correct real-device polyfill, not test-only).</li><li>A <code>moduleNameMapper</code> entry in <code>package.json</code>&#39;s <code>jest</code> config routing <code>isomorphic-webcrypto</code> to a 10-line local shim (<code>jest.webcrypto-shim.js</code>) that hands <code>lib0</code> Node&#39;s native <code>crypto.webcrypto</code> instead, with a no-op <code>ensureSecure()</code> (the one method Node&#39;s implementation lacks that <code>lib0</code> calls).</li></ul><p>Verification for the mobile port as of the §15/16 closeout: TypeScript compiles clean project-wide, the 22 unit tests above pass, and the full existing 53-test mobile suite had zero regressions. Component tests and device flows were added in a follow-up pass — see §9.</p><h2 id="_9-mobile-component-tests-maestro-device-flows-new-2026-10-26" tabindex="-1">9. Mobile component tests + Maestro device flows (new, 2026-10-26) <a class="header-anchor" href="#_9-mobile-component-tests-maestro-device-flows-new-2026-10-26" aria-label="Permalink to &quot;9. Mobile component tests + Maestro device flows (new, 2026-10-26)&quot;">​</a></h2><p>24 <code>@testing-library/react-native</code> component tests across 4 files:</p><table tabindex="0"><thead><tr><th>File</th><th>Cases</th><th>What it covers</th></tr></thead><tbody><tr><td><code>FormattingToolbar.test.tsx</code></td><td>9</td><td>Every toolbar callback fires with the right argument (bold/italic/underline/strikethrough toggle, align, list kind, undo/redo, clear formatting), the color/link modals open and apply, Docs/Ribbon mode switch doesn&#39;t crash</td></tr><tr><td><code>SocialPreview.test.tsx</code></td><td>6</td><td>Placeholder vs. typed text, author name default, X/Twitter tab + character counter + over-limit flag, attached image renders</td></tr><tr><td><code>VersionHistory.test.tsx</code></td><td>3</td><td>Empty state, editor name / &quot;Unknown&quot; fallback, restore calls <code>onRestored</code> with the server&#39;s returned snapshot (REST mocked via <code>jest.mock(&quot;../../../services/api&quot;)</code>)</td></tr><tr><td><code>RichTextEditor.test.tsx</code></td><td>6</td><td>Typing inserts into a <strong>real</strong> <code>Y.Doc</code> (not mocked — exercises the actual CRDT wiring), toolbar bold formats the next typed char, bullet list prefixes the paragraph, undo reverts, <code>onTextChange</code> fires, peer avatar renders</td></tr></tbody></table><p><strong>Defect found and fixed while writing these (test infrastructure, not app code)</strong>: <code>fireEvent.press</code> in this project&#39;s RTL version (14.1.0) combined with React 19 must be wrapped in <code>await act(async () =&gt; ...)</code>. Without it, the state update from a <code>press()</code> in one test leaks past that test&#39;s boundary — the <em>next</em> <code>render()</code> call in the same file silently fails to mount (<code>toJSON()</code> returns <code>null</code>), which then surfaced as a confusing &quot;Unable to find an element with accessibility label: X&quot; on a completely unrelated query two tests later, with nothing in the error pointing at the real cause. Diagnosed by: (1) confirming each failing test passed when run alone (<code>-t &quot;name&quot;</code>), ruling out the test logic itself; (2) a binary-search probe — rendering <code>Modal</code> alone four times in a row (fine), then <code>Select</code> alone three times (fine), ruling those components out; (3) reproducing the exact 3-test failing sequence from the real file in an isolated throwaway test, which revealed <code>toJSON()</code> returning <code>null</code> on the broken render; (4) wrapping the presses in <code>act()</code> in that isolated repro fixed it, then applied the same fix to the real suite. All four test files above use this pattern (<code>async function press(el) { await act(async () =&gt; { fireEvent.press(el); }); }</code>), and <code>VersionHistory.test.tsx</code>&#39;s async <code>api.post</code> flow additionally needed <code>waitFor</code>.</p><p><strong>Maestro device flows</strong> (<code>.maestro/content-writing/*.yaml</code>, 7 flows) and a setup README (<code>.maestro/README.md</code>) were written to cover what unit/component tests structurally cannot: the real app launching, real OS keyboard, real photo picker, real navigation. <strong>Not executed</strong> — this session had no Maestro CLI installed and no running simulator/emulator (headless environment). See <code>.maestro/README.md</code> §1-§4 for install/build/run steps.</p><p>Flows 06 (version history: autosave → diff → restore) and 07 (offline/reconnect: airplane-mode edit → queue → flush, <strong>Android-only</strong>, no iOS equivalent for <code>setAirplaneMode</code>) were added after the initial 5, closing the two single-device gaps originally listed as not covered. Still not attempted — needs two simultaneous device sessions, not a single-device Maestro flow: two-device real-time sync, presence/multi-cursor (see §6 of the README).</p>',39)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
